problems.solution:
import math

def f(x):
    # the landscape with several valleys from the video
    return 2.3 + 1.2 * math.cos(1.3 * x) + 0.06 * (x - 5) ** 2 - 0.5 * math.exp(-((x - 7.3) ** 2) / 0.8)

def df(x, h=1e-5):
    return (f(x + h) - f(x - h)) / (2 * h)

def descend(x0, lr=0.1, steps=500):
    x = x0
    for _ in range(steps):
        x = x - lr * df(x)
    return x

def valleys(starts):
    return sorted(set(round(descend(s), 1) for s in starts))

import numpy as np

def classify(H, tol=1e-9):
    ev = np.linalg.eigvalsh(H)
    if np.any(np.abs(ev) < tol):
        return 'flat'
    if np.all(ev > 0):
        return 'minimum'
    if np.all(ev < 0):
        return 'maximum'
    return 'saddle'
